expected.script:
foreach ($f in Get-ChildItem docs -Filter *.md) {
  Write-Host $f.Name
  Get-Content $f.FullName -TotalCount 3
}

try {
  Remove-Item tmp\cache -Recurse -Force
} catch {
  Write-Warning $_
} finally {
  Write-Host done
}

if (Test-Path dist\index.html) {
  Write-Host 'built'
} else {
  npm run build
  Write-Host 'rebuilt now'
}
